  (function() {
    var uri = window.location.toString();
    if (uri.indexOf("%3D") > 0 || uri.indexOf("?m=1") > 0 || uri.indexOf("&m=1") > 0) {
      var clean = uri.replace(/[?&]m=1/, '').replace(/%3D/g, '');
      window.history.replaceState({}, document.title, clean);
    }
  })();
