// Syllabus Modal Functions function openSyllabusModal(e) { if (e) e.preventDefault(); document.getElementById("syllabusModal").style.display = "flex"; } window.openSyllabusModal = openSyllabusModal;
function closeSyllabusModal() { document.getElementById("syllabusModal").style.display = "none"; document.getElementById("semesterSelect").innerHTML = '<option value="">-- Select Semester --</option>'; document.getElementById("subjectSelect").innerHTML = '<option value="">-- Select Subject --</option>'; document.getElementById("semesterSelect").disabled = true; document.getElementById("subjectSelect").disabled = true; } window.closeSyllabusModal = closeSyllabusModal;
function loadSemesters() { const branch = document.getElementById("branchSelect").value; const semesterSelect = document.getElementById("semesterSelect"); semesterSelect.innerHTML = '<option value="">-- Select Semester --</option>'; document.getElementById("subjectSelect").innerHTML = '<option value="">-- Select Subject --</option>'; document.getElementById("subjectSelect").disabled = true;
if (branch && syllabusData[branch]) { for (let sem in syllabusData[branch]) { let option = document.createElement("option"); option.value = sem; option.text = sem; semesterSelect.appendChild(option); } semesterSelect.disabled = false; } else { semesterSelect.disabled = true; } } window.loadSemesters = loadSemesters;
function loadSubjects() { const branch = document.getElementById("branchSelect").value; const semester = document.getElementById("semesterSelect").value; const subjectSelect = document.getElementById("subjectSelect"); subjectSelect.innerHTML = '<option value="">-- Select Subject --</option>';
if (branch && semester && syllabusData[branch][semester]) { syllabusData[branch][semester].forEach(subject => { let option = document.createElement("option"); option.value = subject; option.text = subject; subjectSelect.appendChild(option); }); subjectSelect.disabled = false; } else { subjectSelect.disabled = true; } } window.loadSubjects = loadSubjects;
function openSyllabus() { const branch = document.getElementById("branchSelect").value; const semester = document.getElementById("semesterSelect").value; const subject = document.getElementById("subjectSelect").value;
if (branch && semester && subject) { const url = syllabusLinks[branch]?.[semester]?.[subject]; if (url) { window.open(url, "_blank"); } else { alert("Study link not available for selected subject. You can join the general community group."); window.open("https://chat.whatsapp.com/K6roXGbgAsFLSV1vdhZEQM", "_blank"); } } else { alert("Please select Branch, Semester, and Subject."); } } window.openSyllabus = openSyllabus;
// PWA Install Prompt Handler let deferredPrompt; const pwaPopup = document.getElementById("pwaPopup"); const pwaInstallBtn = document.getElementById("pwaInstallBtn"); const pwaLaterBtn = document.getElementById("pwaLaterBtn"); const pwaFloatingBtn = document.getElementById("pwaFloatingBtn");
window.addEventListener("beforeinstallprompt", (e) => { e.preventDefault(); deferredPrompt = e; if (pwaPopup) pwaPopup.classList.add("show"); if (pwaFloatingBtn) pwaFloatingBtn.style.display = "flex"; });
if (pwaInstallBtn) { pwaInstallBtn.addEventListener("click", async () => { if (pwaPopup) pwaPopup.classList.remove("show"); if (deferredPrompt) { deferredPrompt.prompt(); await deferredPrompt.userChoice; deferredPrompt = null; } }); }
if (pwaFloatingBtn) { pwaFloatingBtn.addEventListener("click", async () => { if (deferredPrompt) { deferredPrompt.prompt(); await deferredPrompt.userChoice; deferredPrompt = null; } }); }
if (pwaLaterBtn) { pwaLaterBtn.addEventListener("click", () => { if (pwaPopup) pwaPopup.classList.remove("show"); }); }
window.addEventListener("appinstalled", () => { if (pwaPopup) pwaPopup.classList.remove("show"); if (pwaFloatingBtn) pwaFloatingBtn.style.display = "none"; });
// Security Warning / Anti-Inspect Popup let alertTimeout; function showHighAlert() { const popup = document.getElementById('high-alert-popup'); if (!popup) return; popup.classList.add('show'); clearTimeout(alertTimeout); alertTimeout = setTimeout(() => { popup.classList.remove('show'); }, 3500); }
document.addEventListener('contextmenu', function(e) { // Allow normal interactions inside forms and input fields if (['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return; e.preventDefault(); showHighAlert(); });
document.addEventListener('keydown', function(e) { if ( (e.ctrlKey && ['u', 's', 'c'].includes(e.key.toLowerCase())) || e.key === 'F12' ) { if (['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return; e.preventDefault(); showHighAlert(); return false; } }); //
